def _flaky(fail_times):
    """An action that fails its first ``fail_times`` attempts, then succeeds."""

    def action(ctx):
        if ctx.attempt <= fail_times:
            raise RuntimeError("transient failure #{}".format(ctx.attempt))

    return action


